310	  private rateOf(grade: Grade): string | null {
311	    const today = this.session.sheet()?.today;
312	    return today === undefined ? null : (rateInForce(this.ratesOf(grade), today)?.pct ?? null);
313	  }
314	
315	  /** The sum of the figures due on the person's open and settled claims, in cents; null (n/a) when no
316	   *  rate of their grade is in force today and none of their claims keeps a figure. */
317	  private dueCentsOf(person: PersonView): number | null {
318	    const gradeRates = this.ratesOf(person.grade);
319	    let total = 0;
320	    let keptFigure = false;
321	    for (const c of this.claimsOf(person.id)) {
322	      if (!this.countsLive(c)) continue;
323	      const due = claimDueCents(c, gradeRates);
324	      if (due !== null) total += due;
325	      if (keepsFigure(c)) keptFigure = true;
326	    }
327	    return this.rateOf(person.grade) === null && !keptFigure ? null : total;
328	  }
329	
330	  /** The person's due-total with two decimals, or n/a when no rate of their grade is in force today
331	   *  and no claim keeps a figure (settled, or bound by a statement). */
332	  protected personDueTotal(person: PersonView): string {
333	    const due = this.dueCentsOf(person);
334	    return due === null ? 'n/a' : money(due);
335	  }
336	
337	  protected rateSaved(rate: RateView): void {
338	    // Kept as the store lists them: in grade order, then the rate from the start, then by from-date.
339	    this.rates.update((list) => [...list.filter((r) => !sameRate(r, rate)), rate]
340	      .sort((a, b) => a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '')));
341	  }
342	
343	  protected periodAdded(period: PeriodView): void {
344	    // Kept as the store lists them: in date order.
345	    this.periods.update((list) => [...list, period].sort((a, b) => a.from.localeCompare(b.from)));
346	  }
347	
348	  protected periodChanged(period: PeriodView): void {
349	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
350	  }
351	
352	  protected claimAdded(claim: ClaimView): void {
353	    this.claims.update((list) => [claim, ...list]);
354	  }
355	
356	  /** A quick-add's claim, and its person when the quick-add added them. */
357	  protected quickAdded(added: QuickAddView): void {
358	    if (!this.people().some((p) => p.id === added.person.id)) this.people.update((list) => [...list, added.person]);
359	    this.claimAdded(added.claim);
360	  }
361	
362	  protected claimSaved(claim: ClaimView): void {
363	    this.claims.update((list) => list.map((c) => (c.id === claim.id ? claim : c)));
364	  }
365	
366	  private reset(): void {
367	    this.editingId.set(null);
368	    this.error.set('');
369	    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
370	  }
371	
372	  protected edit(person: PersonView): void {
373	    this.personError.set(null);
374	    this.editingId.set(person.id);
375	    this.editingVersion.set(person.version);
376	    this.error.set('');
377	    this.form.setValue({ name: person.name, grade: person.grade }, { emitEvent: false });
378	  }
379	
380	  protected cancel(): void {
381	    this.reset();
382	  }
383	
384	  /** After an edit was refused because someone else saved the person meanwhile: re-read the people
385	   *  and show the person's current values in the editor, keeping the refusal showing. */
386	  private async showCurrent(sheetId: string, id: number): Promise<void> {
387	    try {
388	      const people = await this.api.list(sheetId);
389	      if (this.session.sheet()?.id !== sheetId) return;
390	      this.people.set(people);
391	      const current = people.find((p) => p.id === id);
392	      if (current && this.editingId() === id) {
393	        this.editingVersion.set(current.version);
394	        this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
395	      }
396	    } finally {
397	      this.error.set('Someone else has saved this person since you opened it; the form now shows their changes.');
398	    }
399	  }
400	
401	  protected async submit(): Promise<void> {
402	    // A second submit before the first has answered is ignored, so it stores one record, not two.
403	    if (this.saving()) return;
404	    const sheet = this.session.sheet();
405	    if (!sheet) return;
406	    this.error.set('');
407	    const value = this.form.getRawValue();
408	    if (!value.name.trim()) {
409	      this.error.set('Type a name for the person.');
410	      return;
411	    }
412	    if (!GRADES.includes(value.grade)) {
413	      this.error.set('Choose a grade of A, B or C.');
414	      return;
415	    }
416	    const id = this.editingId();
417	    this.saving.set(true);
418	    try {
419	      if (id === null) {
420	        const added = await this.api.add(sheet.id, { ...value, name: value.name.trim() });
421	        if (this.session.sheet()?.id === sheet.id) this.people.update((list) => [...list, added]);
422	      } else {
423	        const saved = await this.api.update(sheet.id, id,
424	          { ...value, name: value.name.trim(), version: this.editingVersion() });
425	        if (this.session.sheet()?.id === sheet.id) {
426	          this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
427	        }
428	      }
429	      if (this.session.sheet()?.id === sheet.id) this.reset();
430	    } catch (e) {
431	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
432	        await this.showCurrent(sheet.id, id);
433	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
434	        this.error.set('That name is already in use on the sheet.');
435	      } else {
436	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
437	      }
438	    } finally {
439	      this.saving.set(false);
440	    }
441	  }
442	}
